// decodeJSON reads a request body into a T, strictly: the body must be one JSON
// object of at most 1 MB, sent as application/json, with no field T does not have
// and no field of the wrong type. Every way it can fail is a problem that names the
// field to blame, so a client knows what to fix.
func decodeJSON[T any](w http.ResponseWriter, r *http.Request) (T, error) {
	var v T
	if err := requireJSON(r); err != nil {
		return v, err
	}
	dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, maxBody))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&v); err != nil {
		return v, decodeError(err)
	}
	if dec.More() {
		return v, &requestError{status: http.StatusBadRequest, detail: "the body must hold exactly one JSON object"}
	}
	return v, nil
}

// requireJSON refuses a body that is not sent as application/json, such as a form.
func requireJSON(r *http.Request) error {
	mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil || mediaType != "application/json" {
		return &requestError{status: http.StatusUnsupportedMediaType, detail: "send the body as JSON with Content-Type: application/json"}
	}
	return nil
}

// maxBody is the largest JSON request body the API reads.
const maxBody = 1 << 20

// writeJSON writes v as a JSON response. It encodes before writing anything, so a
// value that cannot be encoded still becomes a clean 500 problem. A failed write means
// the client has gone, and there is no one left to tell.
func writeJSON(w http.ResponseWriter, status int, v any) error {
	body, err := json.Marshal(v)
	if err != nil {
		return fmt.Errorf("encode response: %w", err)
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(append(body, '\n'))
	return nil
}

// createTask adds a task to a project.
func (s *server) createTask(w http.ResponseWriter, r *http.Request) error {
	projectID, err := pathID(r, "projectID", "project_id")
	if err != nil {
		return err
	}
	req, err := decodeJSON[createTaskRequest](w, r)
	if err != nil {
		return err
	}
	due, err := parseDate("due_on", req.DueOn)
	if err != nil {
		return err
	}
	t := domain.Task{Title: req.Title, Description: req.Description, DueOn: due, AssigneeID: req.AssigneeID}
	if req.Priority != nil {
		t.Priority = domain.Priority(*req.Priority)
	}
	created, err := s.Tasks.Create(r.Context(), user(r), projectID, t)
	if err != nil {
		return err
	}
	w.Header().Set("Location", "/v1/tasks/"+strconv.FormatInt(created.ID, 10))
	w.Header().Set("ETag", etag(created.Version))
	return writeJSON(w, http.StatusCreated, toTaskResponse(created))
}

// Validate checks every rule a stored task follows.
func (t Task) Validate() error {
	errs := FieldErrors{}
	switch n := utf8.RuneCountInString(t.Title); {
	case n == 0:
		errs.Add("title", "is required")
	case n > MaxTaskTitle:
		errs.Add("title", fmt.Sprintf("must be at most %d characters", MaxTaskTitle))
	}
	if t.Description != nil && utf8.RuneCountInString(*t.Description) > MaxTaskDescription {
		errs.Add("description", fmt.Sprintf("must be at most %d characters", MaxTaskDescription))
	}
	if _, err := ParseStatus(string(t.Status)); err != nil {
		errs.Add("status", "must be todo, doing, or done")
	}
	if !t.Priority.Valid() {
		errs.Add("priority", "must be 1, 2, or 3")
	}
	return errs.Err()
}

